// Actual desktop carrier + UI acceptance. Uses only its synthetic workspace.
// --home creates explicit synthetic tool records via the released Session API.
// The documents/media are generated by the product's actual bundled runtimes.
// Run against an isolated, already-started candidate (never the user's home):
// node tests/desktop-preview-acceptance.mjs --shell wails --cdp http://127.0.0.1:9334
//   --product <candidate/resources/product> --home <isolated-dsh-home>
//   --evidence <ignored-new-evidence-directory> --large
// Electron uses --shell electron with its own CDP endpoint and isolated home.
import assert from 'node:assert/strict'
import { execFile } from 'node:child_process'
import { createRequire } from 'node:module'
import { parseArgs, promisify } from 'node:util'
import { createHash } from 'node:crypto'
import { mkdir, readFile, writeFile } from 'node:fs/promises'
import { basename, join, resolve } from 'node:path'
import { pathToFileURL, fileURLToPath } from 'node:url'

const { values } = parseArgs({ options: { ...Object.fromEntries(['product', 'cdp', 'url-file', 'evidence', 'shell', 'phase', 'home'].map(name => [name, { type: 'string' }])), large: { type: 'boolean' } } })
for (const name of ['product', 'evidence', 'shell']) assert.ok(values[name], `--${name} is required`)
assert.ok(['electron', 'wails', 'web'].includes(values.shell))
if (values.shell !== 'web') assert.equal(new URL(values.cdp).hostname, '127.0.0.1')
const phase = values.phase || 'all'
assert.ok(['all', 'prepare', 'ui'].includes(phase))
const product = resolve(values.product), evidence = resolve(values.evidence)
await mkdir(evidence, { recursive: true })
const fixtureFile = join(evidence, 'fixture.json')
let fixture = await readFile(fixtureFile, 'utf8').then(JSON.parse).catch(() => null)
const previous = await readFile(join(evidence, 'result.json'), 'utf8').then(JSON.parse).catch(() => ({}))
const result = { ...previous, shell: values.shell, syntheticFilesOnly: true, startedAt: new Date().toISOString(), passed: false, checks: previous.checks || [], errors: [] }
const save = () => writeFile(join(evidence, 'result.json'), JSON.stringify(result, null, 2) + '\n')
const saveFixture = () => writeFile(fixtureFile, JSON.stringify(fixture, null, 2) + '\n')
const check = async (name, details = {}) => {
  result.checks = result.checks.filter(row => row.name !== name)
  result.checks.push({ name, passed: true, observedAt: new Date().toISOString(), previewStreamSha256: result.previewStreamSha256, ...details }); await save()
}
const hash = value => createHash('sha256').update(value).digest('hex')
result.product = product
result.previewStreamSha256 = hash(await readFile(join(product, 'd/node_modules/@chatecnu-work/dsh-artifact-preview-native/lib/stream.js')))
result.nativeResourcesManifestSha256 = hash(await readFile(join(product, 'desktop-resources.json')))
const run = promisify(execFile)
const resources = JSON.parse(await readFile(join(product, 'desktop-resources.json'), 'utf8'))
const environment = { ...process.env, ...Object.fromEntries(Object.entries(resources.environment).map(([key, value]) => [key, resolve(product, value)])) }
const shared = join(product, 'd/node_modules/@eduwork/dsh-artifact-services')
const { chromium } = createRequire(join(product, 'd/package.json'))('playwright-core')
const browser = values.shell === 'web'
  ? await chromium.launch({ headless: true, executablePath: environment.DSH_MEDIA_BROWSER })
  : await chromium.connectOverCDP(values.cdp)
const page = values.shell === 'web' ? await browser.newPage({ viewport: { width: 1440, height: 960 }, locale: 'zh-CN' })
  : browser.contexts().flatMap(ctx => ctx.pages()).find(page => values.shell === 'electron' ? page.url().startsWith('dsh-app://app/') : page.url().startsWith('http://wails.localhost/'))
if (values.shell === 'web') {
  const bootstrap = (await readFile(resolve(values['url-file']), 'utf8')).trim()
  assert.equal(new URL(bootstrap).hostname, '127.0.0.1')
  await page.goto(bootstrap, { waitUntil: 'domcontentloaded' })
}
assert.ok(page, 'The explicitly selected desktop page is open')
await page.bringToFront()
page.setDefaultTimeout(20_000)
await page.addLocatorHandler(page.getByRole('dialog', { name: '内测声明' }), async dialog => {
  await dialog.getByRole('button', { name: '继续', exact: true }).click()
})
await page.addLocatorHandler(page.getByRole('dialog', { name: '添加一个 API Key 开始使用' }), async dialog => {
  await dialog.getByRole('button', { name: '稍后配置', exact: true }).click()
})
let sequence = 0
const rpc = async (method, args = {}) => { try { return await page.evaluate(async ({ method, args, id }) => {
  const response = await fetch('/api/' + method, { method: 'POST', signal: AbortSignal.timeout(30_000), headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ type: 'client-request', rpcId: id, method, payload: { args } }) })
  const envelope = await response.json()
  if (!response.ok || !envelope.result?.ok) throw new Error(method + ' failed')
  return envelope.result.value
}, { method, args, id: `desktop-preview-${++sequence}` }) } catch (error) { throw new Error(`${method}: ${error.message}`) } }
const fetchFile = (url, options = {}) => page.evaluate(async ({ url, options }) => {
  const response = await fetch(url, { ...options, signal: AbortSignal.timeout(30_000) })
  const bytes = new Uint8Array(await response.arrayBuffer())
  let text = ''; for (const byte of bytes) text += String.fromCharCode(byte)
  return { status: response.status, headers: Object.fromEntries(response.headers), data: btoa(text), size: bytes.length }
}, { url, options })
const inspect = async () => {
  const session = (await rpc('session/list', { _request: {} })).items.find(row => row.sessionId === fixture.sessionId)
  assert.ok(session)
  const history = await rpc('session/page', { request: { address: { kind: 'session', sessionId: fixture.sessionId }, throughSeq: session.projections?.asOfSeq ?? (fixture.toolFixture ? (fixture.eventCount || 17) - 1 : 0), maxMessages: 100 } })
  return { session, history }
}
const selectSession = async () => {
  await page.reload({ waitUntil: 'domcontentloaded' })
  const notice = page.getByRole('dialog', { name: '内测声明' })
  if (await notice.isVisible().catch(() => false)) await notice.getByRole('button', { name: '继续', exact: true }).click()
  const workspace = page.getByRole('treeitem').getByText(basename(fixture.workspace), { exact: true }).first()
  await workspace.waitFor()
  const row = page.getByRole('treeitem').filter({ has: page.getByText(basename(fixture.workspace), { exact: true }) }).first()
  if (await row.getAttribute('aria-expanded') === 'false') {
    // The row's centre can hit its new-session action. Use the expansion glyph.
    await row.hover() // The official workspace row reveals this glyph on hover.
    await row.locator('span[class*="_chevron"]').click()
  }
  await page.getByRole('treeitem').getByText(fixture.title, { exact: true }).first().click()
  await page.getByRole('banner').getByRole('button', { name: fixture.title, exact: true }).waitFor()
  await page.locator('[contenteditable="true"]').first().waitFor()
}

try {
  assert.ok(fixture?.toolFixture || values.home, '--home is required to create an explicit synthetic publication session; this test never calls a model')
  if (!fixture) {
    const workspace = join(evidence, `preview-workspace-${values.shell}`)
    await mkdir(workspace, { recursive: true })
    const registered = await rpc('workspace/create', { request: { path: workspace } })
    const created = await rpc('session/create', { request: { workspaceId: registered.workspace.workspaceId } })
    fixture = { workspace, workspaceId: registered.workspace.workspaceId, sessionId: created.sessionId,
      title: `Desktop preview acceptance · ${values.shell}`, filesReady: false, turnSubmitted: false }
    await rpc('session/rename', { request: { sessionId: fixture.sessionId, title: fixture.title } })
    await saveFixture()
  }
  assert.equal(resolve(fixture.workspace), join(evidence, `preview-workspace-${values.shell}`))
  const files = fixture.files || ['preview-report.docx', 'preview-table.xlsx', 'preview-slides.pptx', 'preview-audio.wav', 'preview-video.mp4', ...(values.large ? ['preview-large.wav'] : [])]
  fixture.files = files; await saveFixture()
  if (!fixture.filesReady) {
    const office = async (module, filename, spec) => {
      const created = await run(environment.DSH_OFFICE_PYTHON, ['-I', '-X', 'utf8', join(shared, 'python/runner.py'), module,
        '--project-root', fixture.workspace, '--output', join(fixture.workspace, filename), '--overwrite', '--spec-json', JSON.stringify(spec)], { env: environment, windowsHide: true, encoding: 'utf8' })
      assert.equal(JSON.parse(created.stdout).ok, true)
    }
    await office('documents.create_document', files[0], { blocks: [{ type: 'title', text: 'Electron / Wails 预览验收' }, { type: 'paragraph', text: 'Synthetic report. 样本40例，完成30例，完成率75%。' }] })
    await office('spreadsheets.create_workbook', files[1], { sheets: [{ name: 'Summary', header: true, rows: [['Stage', 'Cases', 'Completed'], ['A', 40, 30], ['B', 40, 36]] }] })
    await office('presentations.create_presentation', files[2], { slides: [{ layout: 'cover', title: 'Desktop Preview', subtitle: 'One shared renderer' }, { layout: 'metrics', title: 'Synthetic data', metrics: [{ value: '75%', label: 'A' }, { value: '90%', label: 'B' }] }] })
    const { createMediaRuntime, getMediaFFmpegPath } = await import(pathToFileURL(join(shared, 'lib/runtime.js')))
    const media = await createMediaRuntime({ environment }), ffmpeg = await getMediaFFmpegPath({ runtime: media })
    await run(ffmpeg, ['-y', '-nostdin', '-v', 'error', '-f', 'lavfi', '-i', 'sine=frequency=440:duration=1.2', '-ar', '16000', '-ac', '1', join(fixture.workspace, files[3])], { windowsHide: true })
    // The minimal FFmpeg supports BMP/image2, but not color or rawvideo inputs.
    const bmp = Buffer.alloc(54 + 640 * 360 * 3)
    bmp.write('BM'); bmp.writeUInt32LE(bmp.length, 2); bmp.writeUInt32LE(54, 10); bmp.writeUInt32LE(40, 14)
    bmp.writeInt32LE(640, 18); bmp.writeInt32LE(360, 22); bmp.writeUInt16LE(1, 26); bmp.writeUInt16LE(24, 28)
    for (let offset = 54; offset < bmp.length; offset += 3) { bmp[offset] = 160; bmp[offset + 1] = 120; bmp[offset + 2] = 60 }
    const frame = join(evidence, 'synthetic-frame.bmp'); await writeFile(frame, bmp)
    await run(ffmpeg, ['-y', '-nostdin', '-v', 'error', '-loop', '1', '-framerate', '12', '-i', frame, '-t', '1.2', '-c:v', 'libx264', '-pix_fmt', 'yuv420p', '-preset', 'ultrafast', join(fixture.workspace, files[4])], { windowsHide: true })
    if (files.includes('preview-large.wav')) {
      const wave = Buffer.alloc(40 * 1024 * 1024 + 44)
      wave.write('RIFF', 0); wave.writeUInt32LE(wave.length - 8, 4); wave.write('WAVEfmt ', 8)
      wave.writeUInt32LE(16, 16); wave.writeUInt16LE(1, 20); wave.writeUInt16LE(1, 22)
      wave.writeUInt32LE(16000, 24); wave.writeUInt32LE(32000, 28); wave.writeUInt16LE(2, 32); wave.writeUInt16LE(16, 34)
      wave.write('data', 36); wave.writeUInt32LE(wave.length - 44, 40)
      await writeFile(join(fixture.workspace, 'preview-large.wav'), wave)
    }
    fixture.filesReady = true; await saveFixture()
  }
  await check('synthetic-office-and-media-files', { files })
  if (values.home && !fixture.toolFixture) {
    await run(process.execPath, [fileURLToPath(new URL('./desktop-preview-fixture.mjs', import.meta.url)), product, resolve(values.home), evidence], { windowsHide: true })
    fixture = JSON.parse(await readFile(fixtureFile, 'utf8'))
  }
  if (fixture.toolFixture && !fixture.attached) {
    await rpc('session/create', { request: { workspaceId: fixture.workspaceId, sessionId: fixture.sessionId } })
    fixture.attached = true; await saveFixture()
  }
  if (fixture.toolFixture) await rpc('session/rename', { request: { sessionId: fixture.sessionId, title: fixture.title } })

  if (phase !== 'ui') {
    const previews = {}
    for (const file of files) {
      const preview = await rpc('artifactPreview/read', { sessionId: fixture.sessionId, relativePath: file })
      assert.match(preview.downloadUrl, /^\/api\/artifactPreview\/file\?token=[A-Za-z0-9_-]{32}(?:&download=1)?$/)
      const original = await readFile(join(fixture.workspace, file))
      const full = original.length > 32 * 1024 * 1024
        ? await page.evaluate(async url => { const response = await fetch(url, { signal: AbortSignal.timeout(30_000) }); const bytes = await response.arrayBuffer(); const digest = await crypto.subtle.digest('SHA-256', bytes); return { status: response.status, hash: Array.from(new Uint8Array(digest), byte => byte.toString(16).padStart(2, '0')).join('') } }, preview.downloadUrl)
        : await fetchFile(preview.downloadUrl)
      assert.equal(full.status, 200); assert.equal(full.hash || hash(Buffer.from(full.data, 'base64')), hash(original))
      const head = await fetchFile(preview.downloadUrl, { method: 'HEAD' })
      assert.equal(head.status, 200); assert.equal(head.size, 0); assert.equal(Number(head.headers['content-length']), original.length)
      assert.match(head.headers['content-disposition'], /^attachment; filename\*=UTF-8''/)
      const range = await fetchFile(preview.downloadUrl, { headers: { Range: 'bytes=0-31' } })
      assert.equal(range.status, 206); assert.deepEqual(Buffer.from(range.data, 'base64'), original.subarray(0, 32))
      assert.equal(range.headers['content-range'], `bytes 0-31/${original.length}`)
      const invalid = await fetchFile(preview.downloadUrl, { headers: { Range: `bytes=${original.length}-` } })
      assert.equal(invalid.status, 416)
      if (file === 'preview-large.wav') {
        const blockedReaderCheck = await page.evaluate(async url => {
          const response = await fetch(url, { signal: AbortSignal.timeout(15_000) })
          const reader = response.body.getReader()
          try {
            await reader.read()
            await new Promise(resolve => setTimeout(resolve, 250))
            const started = performance.now()
            const rpcResponse = await fetch('/api/session/list', { method: 'POST', signal: AbortSignal.timeout(5_000), headers: { 'content-type': 'application/json' }, body: JSON.stringify({ type: 'client-request', rpcId: 'desktop-preview-backpressure', method: 'session/list', payload: { args: { _request: {} } } }) })
            const envelope = await rpcResponse.json()
            if (!envelope.result?.ok) throw new Error('Session RPC failed while a media reader was paused')
            return { responsive: true, elapsedMs: Math.round(performance.now() - started) }
          } finally { await reader.cancel() }
        }, preview.downloadUrl)
        assert.ok(blockedReaderCheck.elapsedMs < 5_000)
        await check('stalled-media-reader-does-not-block-session-rpc', blockedReaderCheck)
      }
      previews[file] = { bytes: original.length, sha256: hash(original), encoding: preview.encoding, office: preview.officePreview, range: range.headers['content-range'] }
      if (preview.officePreview) {
        assert.equal(preview.mime, 'text/html'); assert.ok(preview.data.includes('<'))
        await writeFile(join(evidence, `${file}.preview.html`), preview.data)
      }
    }
    assert.equal(previews['preview-slides.pptx'].office.pageCount, 2)
    await check('official-carrier-preview-download-head-range', { protocol: new URL(page.url()).protocol, files: previews })
    if (!fixture.uploadVerified) {
      await selectSession()
      const editor = page.locator('[contenteditable="true"]').first()
      await editor.fill('保留附件的上传验收草稿 ')
      const attachments = [
        { name: '第一份 (1).txt', mimeType: 'text/plain', buffer: Buffer.from('first synthetic attachment') },
        { name: '第二份 (2).csv', mimeType: 'text/csv', buffer: Buffer.from('x,y\n1,2\n') },
        { name: '第三份.md', mimeType: 'text/markdown', buffer: Buffer.from('# third synthetic attachment') },
      ]
      const picker = page.locator('input[type="file"][multiple]').first()
      await picker.setInputFiles(attachments.slice(0, 2))
      for (const file of attachments.slice(0, 2)) await page.getByText(file.name, { exact: true }).last().waitFor()
      await picker.setInputFiles(attachments.slice(2))
      for (const file of attachments) await page.getByText(file.name, { exact: true }).last().waitFor()
      await page.screenshot({ path: join(evidence, 'three-uploaded-files.png') })
      await check('official-multiple-upload-three-files', { attachments: attachments.map(file => file.name) })
      await page.getByRole('button', { name: '新建会话', exact: true }).first().click()
      await page.getByRole('button', { name: '选择工作区', exact: true }).waitFor()
      await page.getByRole('treeitem').getByText(fixture.title, { exact: true }).first().click()
      await page.getByRole('banner').getByRole('button', { name: fixture.title, exact: true }).waitFor()
      for (const file of attachments) await page.getByText(file.name, { exact: true }).last().waitFor()
      assert.match(await editor.innerText(), /保留附件的上传验收草稿/)
      assert.doesNotMatch(await page.locator('body').innerText(), /文件卡片未能加入|文件上传失败|Failed to load plugins/)
      fixture.uploadVerified = true; await saveFixture()
      await check('official-multiple-upload-and-session-reentry', { attachments: attachments.map(file => file.name) })
    }
  }
  if (phase === 'prepare') {
    result.prepared = true
  } else {
    let final, idle = 0
    for (let attempt = 0; attempt < 160; attempt++) {
      final = await inspect(); idle = final.session.running ? 0 : idle + 1
      if (idle >= 3) break
      await new Promise(resolve => setTimeout(resolve, 750))
    }
    assert.ok(idle >= 3, 'The synthetic publication session is idle')
    const events = final.history.records.filter(record => record.type === 'event').map(record => record.event)
    const messages = events.filter(event => event.type === 'assistant/message')
    assert.ok(messages.length > 0, 'The synthetic closing reply provides file card fixtures')
    for (const file of files) assert.ok(JSON.stringify(messages).includes(file))
    assert.equal(events.filter(event => event.type === 'tool/call').length, files.length)
    assert.equal(events.filter(event => event.type === 'deliverables/presented').length, files.length)
    await check('synthetic-published-file-session', { syntheticToolEvents: true, realModelGeneration: false })
    await rpc('session/rename', { request: { sessionId: fixture.sessionId, title: fixture.title } })
    await selectSession()
    const more = page.getByRole('button', { name: /展开全部 \d+ 个交付文件/ }).last()
    if (await more.isVisible().catch(() => false)) await more.click()
    assert.equal(await page.locator('[data-presented-file]').count(), files.length)
    assert.equal(await page.locator('[data-chatecnu-artifact-row]').count(), 0, 'Do not duplicate the official delivered-file row')
    for (const file of files) {
      await page.getByRole('button', { name: `在侧边栏预览 ${file}`, exact: true }).click()
      const panel = page.locator('[data-eduwork-artifact-tab]:visible')
      await panel.waitFor()
      if (/\.(docx|xlsx|pptx)$/.test(file)) {
        const frame = panel.frameLocator('iframe[data-office-file-preview]')
        // A previous acceptance run may have persisted page 2. Begin this
        // two-page assertion at page 1 using the same control as the user.
        if (file.endsWith('pptx')) {
          const pageNumber = panel.getByRole('spinbutton', { name: '当前页码', exact: true })
          await pageNumber.fill('1')
          await pageNumber.press('Enter')
        }
        await frame.locator('body').waitFor()
        await frame.locator('body').filter({ hasText: file.endsWith('docx') ? /Synthetic report/ : file.endsWith('xlsx') ? /Cases/ : /Desktop Preview/ }).waitFor()
        assert.equal(await panel.getByRole('button', { name: '源码', exact: true }).count(), 0)
        if (file.endsWith('pptx')) {
          await frame.getByText('Desktop Preview', { exact: true }).waitFor()
          await panel.getByRole('button', { name: '下一页', exact: true }).click()
          await frame.getByText('Synthetic data', { exact: true }).waitFor()
        }
      } else {
        const tag = file.endsWith('wav') ? 'audio' : 'video'
        await panel.locator(tag).waitFor()
        await panel.locator(tag).evaluate(async media => {
          if (media.readyState < 1) await new Promise((resolve, reject) => { const timeout = setTimeout(() => reject(new Error('native media metadata timed out')), 15_000); media.addEventListener('loadedmetadata', () => { clearTimeout(timeout); resolve() }, { once: true }); media.addEventListener('error', () => { clearTimeout(timeout); reject(new Error('native media decode failed')) }, { once: true }) })
          if (!(media.duration > 0)) throw new Error('Missing media duration')
          await media.play()
        })
        await page.waitForFunction(tag => document.querySelector(`[data-eduwork-artifact-tab] ${tag}`)?.currentTime > .1, tag)
        const state = await panel.locator(tag).evaluate(media => { media.pause(); return { duration: media.duration, width: media.videoWidth, height: media.videoHeight, currentTime: media.currentTime, source: media.currentSrc } })
        assert.match(state.source, /\/api\/artifactPreview\/file\?token=/)
        if (file === 'preview-large.wav' || tag === 'video') {
          await panel.locator(tag).evaluate(async (media, large) => {
            const target = large ? media.duration - 2 : media.duration * .6
            await new Promise((resolve, reject) => { const timeout = setTimeout(() => reject(new Error('native media seek timed out')), 15_000); media.addEventListener('seeked', () => { clearTimeout(timeout); resolve() }, { once: true }); media.addEventListener('error', () => { clearTimeout(timeout); reject(new Error('native media seek failed')) }, { once: true }); media.currentTime = target })
            if (Math.abs(media.currentTime - target) > 0.1) throw new Error('Large media seek position mismatch')
          }, file === 'preview-large.wav')
          state.seekVerified = true
        }
        delete state.source // Private expiring capability URLs never enter evidence.
        await check(`native-${file}-playback`, state)
      }
      await page.screenshot({ path: join(evidence, `${file}.png`) })
      // Chromium's custom-protocol carrier must produce a native download event.
      const [download] = await Promise.all([page.waitForEvent('download'), panel.getByRole('link', { name: '下载', exact: true }).click()])
      const filenamePreserved = download.suggestedFilename() === file
      if (!filenamePreserved) result.errors.push(`Download filename was not preserved for ${file}; capability-derived names are redacted`)
      const downloaded = join(evidence, `download-${file}`)
      await download.saveAs(downloaded)
      assert.equal(hash(await readFile(downloaded)), hash(await readFile(join(fixture.workspace, file))))
      await check(`actual-ui-preview-and-download-${file}`, { passed: filenamePreserved, filenamePreserved, screenshot: `${file}.png`, download: basename(downloaded) })
    }
    // Studio follows the official Sidebar start page; no extra product button.
    await page.getByRole('button', { name: '新标签页', exact: true }).click()
    await page.getByRole('button', { name: 'Studio 从工作区资料创建成果', exact: true }).click()
    await page.locator('[data-knowledge-studio-capability="report"]').waitFor()
    await page.locator('[data-sidebar-right-panel]').waitFor()
    await page.getByRole('tab', { name: /preview-slides\.pptx/ }).click()
    await page.locator('[data-eduwork-artifact-tab]:visible iframe[data-office-file-preview]').waitFor()
    await page.screenshot({ path: join(evidence, 'studio-and-shared-file-tabs.png') })
    await check('studio-and-shared-file-sidebar-coexist')
    result.passed = result.errors.length === 0
    if (!result.passed) process.exitCode = 1
  }
} catch (error) {
  result.errors.push(String(error.message))
  await page.screenshot({ path: join(evidence, 'failure.png') }).catch(() => {})
  await writeFile(join(evidence, 'failure.txt'), await page.locator('body').innerText().catch(() => 'Page unavailable'))
  process.exitCode = 1
} finally {
  result.fixture = fixture ? { sessionId: fixture.sessionId, workspace: fixture.workspace } : undefined
  result.finishedAt = new Date().toISOString()
  await save(); await browser.close()
  console.log(JSON.stringify({ passed: result.passed, prepared: result.prepared, checks: result.checks.length, evidence, errors: result.errors }))
}
